"""Frozen output generated by upstream TS, not by the Python implementation."""
import importlib.util
from pathlib import Path

def test_upstream_chart_parity():
    root=Path(__file__).resolve().parents[1]
    spec=importlib.util.spec_from_file_location('parity_check',root/'scripts/verify_upstream_parity.py')
    module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
    report=module.run(root/'tests/fixtures/upstream-parity.json.gz')
    assert report['total']==2528
    assert report['reference_errors']==8  # upstream rejects leap-6 day 30, origin-month, 2017
    assert not report['mismatches'], report['examples']
